// ── N-Queens — place n queens with no row/col/diagonal conflicts ─
// Time: O(n!) in worst case, but heavy pruning makes it practical.
// Space: O(n) for the board state and recursion stack.

function solveNQueens(n) {
  const solutions = [];
  const cols    = new Set(); // attacked columns
  const diag1   = new Set(); // attacked \ diagonals (row - col)
  const diag2   = new Set(); // attacked / diagonals (row + col)
  const board   = [];

  function backtrack(row) {
    if (row === n) {
      // All n queens placed — record the board
      solutions.push(board.map(col =>
        '.'.repeat(col) + 'Q' + '.'.repeat(n - col - 1)
      ));
      return;
    }
    for (let col = 0; col < n; col++) {
      // Pruning: skip if this cell is attacked
      if (cols.has(col) || diag1.has(row - col) || diag2.has(row + col)) continue;

      // Choose
      cols.add(col); diag1.add(row - col); diag2.add(row + col);
      board.push(col);

      backtrack(row + 1); // Explore

      // Undo (backtrack)
      cols.delete(col); diag1.delete(row - col); diag2.delete(row + col);
      board.pop();
    }
  }

  backtrack(0);
  return solutions;
}

console.log(solveNQueens(4).length); // 2  (two valid 4-queen configurations)
console.log(solveNQueens(8).length); // 92

// ── Generate Permutations — O(n! * n) ─────────────────────────
function permutations(nums) {
  const result = [];
  const used   = new Array(nums.length).fill(false);
  const path   = [];

  function backtrack() {
    if (path.length === nums.length) { result.push([...path]); return; }
    for (let i = 0; i < nums.length; i++) {
      if (used[i]) continue; // pruning: skip used elements
      used[i] = true;  path.push(nums[i]);
      backtrack();
      used[i] = false; path.pop();
    }
  }

  backtrack();
  return result;
}
console.log(permutations([1, 2, 3]).length); // 6

// ── Generate All Subsets (Power Set) — O(2^n * n) ─────────────
function subsets(nums) {
  const result = [];
  function backtrack(start, path) {
    result.push([...path]); // every partial path is a valid subset
    for (let i = start; i < nums.length; i++) {
      path.push(nums[i]);       // include nums[i]
      backtrack(i + 1, path);   // recurse on remaining elements
      path.pop();               // exclude nums[i] (backtrack)
    }
  }
  backtrack(0, []);
  return result;
}
console.log(subsets([1, 2, 3]).length); // 8 (2^3)

// ── Sudoku Solver — constraint propagation + backtracking ──────
// board[row][col] is '.' for empty, '1'-'9' for filled.
function solveSudoku(board) {
  function isValid(row, col, num) {
    const boxRow = Math.floor(row / 3) * 3;
    const boxCol = Math.floor(col / 3) * 3;
    for (let i = 0; i < 9; i++) {
      if (board[row][i] === num) return false;         // row conflict
      if (board[i][col] === num) return false;         // col conflict
      if (board[boxRow + Math.floor(i / 3)]
              [boxCol + i % 3] === num) return false;  // box conflict
    }
    return true;
  }

  function backtrack() {
    for (let row = 0; row < 9; row++) {
      for (let col = 0; col < 9; col++) {
        if (board[row][col] !== '.') continue; // already filled
        for (let d = 1; d <= 9; d++) {
          const num = String(d);
          if (!isValid(row, col, num)) continue; // pruning
          board[row][col] = num;   // choose
          if (backtrack()) return true; // explore
          board[row][col] = '.';   // undo
        }
        return false; // no digit worked — backtrack
      }
    }
    return true; // all cells filled
  }

  backtrack();
}

